end

local function BUILD_TOP_VALUES(R, startRegister, topBase, topValues)
    if topBase == nil or topValues == nil then
        error("TOP used without dynamic producer")
    end

    if topBase < startRegister then
        error("invalid TOP range")
    end

    local result = {n = 0}
    local n = 0

    for register = startRegister, topBase - 1 do
        n += 1
        result[n] = R[register]
    end

    for i = 1, topValues.n do
        n += 1
        result[n] = topValues[i]
    end

    result.n = n

    return result
end

local function CALL_TOP_PACK(fn, R, startRegister, topBase, topValues)
    local args = BUILD_TOP_VALUES(
        R,
        startRegister,
        topBase,
        topValues
    )

    return table.pack(
        fn(
            table.unpack(args, 1, args.n)
        )
    )
end

local function SETLIST_FIXED(target, offset, R, startRegister, count)
    for i = 1, count do
        target[offset + i] = R[startRegister + i - 1]
    end
end

local function SETLIST_TOP(target, offset, R, startRegister, topBase, topValues)
    local values = BUILD_TOP_VALUES(
        R,
        startRegister,
        topBase,
        topValues
    )

    for i = 1, values.n do
        target[offset + i] = values[i]
    end
end

local function CLEAR_REGS(R, firstRegister, lastRegister)
    for register = firstRegister, lastRegister do
        R[register] = nil
    end
end


